def _coerce(raw):
    """Coerce a raw value string to bool/int/float/str per the spec."""
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    lowered = raw.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    try:
        return int(raw)
    except ValueError:
        pass
    try:
        return float(raw)
    except ValueError:
        pass
    return raw


def parse_config(text):
    config = {}
    section = ""
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        if "=" not in line:
            continue
        key, _, value = line.partition("=")
        config.setdefault(section, {})[key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    if "." in dotted:
        section, key = dotted.split(".", 1)
    else:
        section, key = "", dotted
    return config.get(section, {}).get(key, default)

